<?php require 'config.php';require 'includes/functions.php';need_role(['patient']);verify();if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['appointment_id']??0);$rating=max(1,min(5,(int)($_POST['rating']??5)));$comment=trim($_POST['comment']??'');$q=$pdo->prepare("INSERT INTO reviews(appointment_id,doctor_id,patient_id,rating,comment) SELECT id,doctor_id,patient_id,?,?,? FROM appointments WHERE id=? AND patient_id=? AND status='completed'");$q->execute([$rating,$comment,$id,user()['id']]);flash('Thank you for your review.');go('dashboard.php');}$id=(int)($_GET['appointment']??$_POST['appointment_id']??0);$title='Doctor review';require 'includes/header.php';?><div class="formbox"><h1>Rate your doctor</h1><form method="post"><?=csrf()?><input type="hidden" name="appointment_id" value="<?=$id?>"><label>Rating<select name="rating"><option value="5">5 - Excellent</option><option value="4">4 - Very good</option><option value="3">3 - Good</option><option value="2">2 - Fair</option><option value="1">1 - Poor</option></select></label><label>Review<textarea name="comment" maxlength="1000"></textarea></label><button class="btn">Submit review</button></form></div><?php require 'includes/footer.php';?>